using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .Use(new OpenAIClient(apiKey)
        .GetChatClient(modelId)
        .AsIChatClient()));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteStore>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteStore = host.Services.GetRequiredService<NoteStore>();
var tools = host.Services.GetRequiredService<ResearchTools>();

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the impact of large language models on software engineering in 2025";

Console.WriteLine($"🔍 Researching: {topic}\n");

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [
        AIFunctionFactory.Create(tools.SearchWeb),
        AIFunctionFactory.Create(tools.TakeNote),
        AIFunctionFactory.Create(tools.GetNotes),
    ],
};

var systemPrompt = """
    You are a research agent. Your goal is to research a given topic thoroughly.

    Workflow:
    1. Search the web for information on the topic (make 2-3 searches with different queries).
    2. Take notes on the key findings from each search.
    3. Review all your notes.
    4. Provide a final summary of your research findings.

    Always take notes before summarizing. Be thorough but concise.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n📋 Research Summary:");
Console.WriteLine(new string('─', 60));
Console.WriteLine(response.Text);
Console.WriteLine(new string('─', 60));

if (noteStore.Notes.Count > 0)
{
    Console.WriteLine($"\n📝 Notes taken during research ({noteStore.Notes.Count}):");
    foreach (var (i, note) in noteStore.Notes.Select((n, i) => (i, n)))
    {
        Console.WriteLine($"  {i + 1}. {note}");
    }
}

// --- Tool definitions and supporting types ---

public sealed class NoteStore
{
    private readonly List<string> _notes = [];
    public IReadOnlyList<string> Notes => _notes;

    public void Add(string note)
    {
        _notes.Add(note);
    }
}

public sealed class ResearchTools(NoteStore noteStore)
{
    [Description("Search the web for information on a query. Returns search result snippets.")]
    public string SearchWeb(
        [Description("The search query to look up")] string query)
    {
        // Simulated web search results for demonstration purposes.
        // Replace with a real search API (e.g., Bing Search API) for production use.
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        var results = query.ToLowerInvariant() switch
        {
            var q when q.Contains("llm") || q.Contains("large language model") =>
                """
                1. "LLMs have transformed code generation, with studies showing 30-50% productivity gains in routine tasks." - ACM Computing Surveys 2025
                2. "GitHub Copilot and similar tools now assist over 40 million developers worldwide." - GitHub Blog 2025
                3. "Concerns remain about code quality, security vulnerabilities, and over-reliance on AI-generated code." - IEEE Software 2025
                """,
            var q when q.Contains("software engineering") || q.Contains("developer") =>
                """
                1. "AI-assisted development is reshaping roles: developers spend more time reviewing and less time writing boilerplate." - ThoughtWorks Tech Radar 2025
                2. "Test generation and documentation are among the highest-value LLM applications in SE." - Microsoft Research 2025
                3. "The software engineering job market is shifting toward AI-augmented roles requiring prompt engineering skills." - Stack Overflow Survey 2025
                """,
            var q when q.Contains("impact") || q.Contains("effect") || q.Contains("future") =>
                """
                1. "By 2026, 80% of professional developers will use AI coding assistants daily." - Gartner Prediction
                2. "Open-source LLMs are closing the gap with proprietary models for code tasks." - Papers With Code 2025
                3. "Enterprise adoption requires robust guardrails: code review, testing, and security scanning remain essential." - OWASP 2025
                """,
            _ =>
                $"""
                1. "Research on '{query}' shows growing academic and industry interest." - Google Scholar 2025
                2. "Multiple recent publications address {query} from both theoretical and practical angles." - arXiv 2025
                3. "Industry reports indicate significant investment in {query}-related technologies." - McKinsey 2025
                """,
        };

        return results;
    }

    [Description("Take a note to remember a key finding during research.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        noteStore.Add(note);
        Console.WriteLine($"  📝 Note taken: {note[..Math.Min(note.Length, 80)]}...");
        return $"Note saved. You now have {noteStore.Notes.Count} note(s).";
    }

    [Description("Retrieve all notes taken so far during this research session.")]
    public string GetNotes()
    {
        if (noteStore.Notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n", noteStore.Notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

